      <p class="subtitle">Send a message to support and we&apos;ll get back to you as soon as possible.</p>

      <form id="contact-form" novalidate>
        <div class="form-field" data-field="fullName">
          <label for="fullName">Full name <span class="required" aria-hidden="true">*</span></label>
          <input id="fullName" name="fullName" type="text" autocomplete="name" required placeholder="Alex Morgan" aria-describedby="fullName-help fullName-error" />
          <div class="helper-text" id="fullName-help">Please enter your first and last name.</div>
          <div class="validation-message" id="fullName-error" aria-live="polite"></div>
        </div>

        <div class="form-field" data-field="email">
          <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
          <input id="email" name="email" type="email" autocomplete="email" required placeholder="alex@example.com" aria-describedby="email-help email-error" />
          <div class="helper-text" id="email-help">We&apos;ll use this to reply to your message.</div>
          <div class="validation-message" id="email-error" aria-live="polite"></div>
        </div>

        <div class="form-field" data-field="phone">
          <label for="phone">Phone number</label>
          <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="+1 (555) 123-4567" aria-describedby="phone-help phone-error" />
          <div class="helper-text" id="phone-help">Optional. Use digits, spaces, parentheses, dashes, or a leading +, for example +1 (555) 123-4567.</div>
          <div class="validation-message" id="phone-error" aria-live="polite"></div>
        </div>

