        <p class="success" id="success-message" role="status">Your message is ready to send.</p>
      </form>
    </section>
  </main>

  <script>
    (() => {
      const form = document.getElementById('contact-form');
      const successMessage = document.getElementById('success-message');
      const fields = {
        fullName: {
          input: document.getElementById('fullName'),
          error: document.getElementById('fullName-error'),
          field: document.querySelector('[data-field="fullName"]'),
          validate(value) {
            if (!value.trim()) return 'Full name is required.';
            if (value.trim().split(/\s+/).length < 2) return 'Please enter your first and last name.';
            return '';
