        </div>
      `;

      const SupportForm = () => `
        <main class="page">
          <section class="card" aria-labelledby="support-title">
            <div class="eyebrow">Support</div>
            <h1 id="support-title">Contact our team</h1>
            <p class="subtitle">Send a message to support and we&apos;ll get back to you as soon as possible.</p>

