    }

    .success.is-visible { display: block; }

    @media (max-width: 640px) {
      .card { padding: 24px 18px; border-radius: 20px; }
      .actions { justify-content: stretch; }
      button { width: 100%; }
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    (() => {
      const root = document.getElementById('root');

      const FormField = ({ name, label, type, required, autocomplete, placeholder, helperText }) => `
        <div class="form-field" data-field="${name}">
          <label for="${name}">${label}${required ? ' <span class="required" aria-hidden="true">*</span>' : ''}</label>
          <input id="${name}" name="${name}" type="${type}" ${autocomplete ? `autocomplete="${autocomplete}"` : ''} ${required ? 'required' : ''} placeholder="${placeholder}" aria-describedby="${name}-help ${name}-error" />
          <div class="helper-text" id="${name}-help">${helperText}</div>
          <div class="validation-message" id="${name}-error" aria-live="polite"></div>
        </div>
      `;

      const SupportForm = () => `
        <main class="page">
          <section class="card" aria-labelledby="support-title">
            <div class="eyebrow">Support</div>
            <h1 id="support-title">Contact our team</h1>
            <p class="subtitle">Send a message to support and we&apos;ll get back to you as soon as possible.</p>

            <form id="contact-form" novalidate>
              ${FormField({
                name: 'fullName',
                label: 'Full name',
                type: 'text',
                required: true,
                autocomplete: 'name',
                placeholder: 'Alex Morgan',
                helperText: 'Please enter your first and last name.'
              })}
              ${FormField({
                name: 'email',
                label: 'Email address',
                type: 'email',
                required: true,
                autocomplete: 'email',
                placeholder: 'alex@example.com',
                helperText: "We&apos;ll use this to reply to your message."
              })}
              ${FormField({
                name: 'phone',
                label: 'Phone number',
                type: 'tel',
                required: false,
                autocomplete: 'tel',
                placeholder: '+1 (555) 123-4567',
                helperText: 'Optional. Use digits, spaces, parentheses, dashes, or a leading +, for example +1 (555) 123-4567.'
              })}

              <div class="actions">
                <button type="submit">Send message</button>
              </div>

              <p class="success" id="success-message" role="status">Your message is ready to send.</p>
            </form>
          </section>
        </main>
      `;

      root.innerHTML = SupportForm();

      const form = document.getElementById('contact-form');
      const successMessage = document.getElementById('success-message');
      const fields = {
        fullName: {
          input: document.getElementById('fullName'),
          error: document.getElementById('fullName-error'),
          field: document.querySelector('[data-field="fullName"]'),
          validate(value) {
            if (!value.trim()) return 'Full name is required.';
            if (value.trim().split(/\s+/).length < 2) return 'Please enter your first and last name.';
            return '';
          }
        },
        email: {
          input: document.getElementById('email'),
          error: document.getElementById('email-error'),
          field: document.querySelector('[data-field="email"]'),
          validate(value) {
            if (!value.trim()) return 'Email address is required.';
            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailPattern.test(value.trim())) return 'Please enter a valid email address.';
            return '';
          }
        },
        phone: {
          input: document.getElementById('phone'),
          error: document.getElementById('phone-error'),
          field: document.querySelector('[data-field="phone"]'),
          validate(value) {
            const trimmed = value.trim();
            if (!trimmed) return '';
            const phonePattern = /^\+?[0-9\s().-]{7,}$/;
            const digits = trimmed.replace(/\D/g, '');
            if (!phonePattern.test(trimmed) || digits.length < 7 || digits.length > 15) {
              return 'Please enter a valid phone number in the expected format.';
            }
            return '';
          }
        }
      };

      const setError = (name, message) => {
        const { input, error, field } = fields[name];
        error.textContent = message;
        field.classList.toggle('has-error', Boolean(message));
        input.setAttribute('aria-invalid', String(Boolean(message)));
      };

      const validateField = (name) => {
        const { input, validate } = fields[name];
        const message = validate(input.value);
        setError(name, message);
        return !message;
      };

      Object.entries(fields).forEach(([name, config]) => {
        config.input.addEventListener('blur', () => validateField(name));
        config.input.addEventListener('input', () => {
          if (config.error.textContent) validateField(name);
          successMessage.classList.remove('is-visible');
        });
      });

      form.addEventListener('submit', (event) => {
        event.preventDefault();

        const isValid = ['fullName', 'email', 'phone'].map(validateField).every(Boolean);
        successMessage.classList.toggle('is-visible', isValid);

        if (isValid) {
          successMessage.textContent = 'Your message is ready to send.';
        } else {
          successMessage.textContent = '';
        }
      });
    })();
  </script>
</body>
</html>
