       --field-bg: rgba(15, 23, 42, 0.88);
       --field-border: rgba(148, 163, 184, 0.24);
       --field-focus: #7c3aed;
       --accent: #8b5cf6;
       --accent-strong: #a78bfa;
       --error: #fb7185;
       --success: #34d399;
       --shadow: 0 24px 80px rgba(2, 6, 23, 0.5);
     }

     * { box-sizing: border-box; }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, rgba(139, 92, 246, 0.18), transparent 35%),
         linear-gradient(180deg, #08101f 0%, #0b1020 45%, #090d17 100%);
       display: grid;
       place-items: center;
       padding: 32px 16px;
     }

     .page {
       width: 100%;
       max-width: 760px;
     }

     .card {
       background: var(--panel);
       border: 1px solid var(--panel-border);
       border-radius: 24px;
       box-shadow: var(--shadow);
       padding: 32px;
       backdrop-filter: blur(18px);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 12px;
       border-radius: 999px;
       background: rgba(124, 58, 237, 0.12);
       color: var(--accent-strong);
       font-size: 0.88rem;
       font-weight: 600;
       margin-bottom: 16px;
     }

     h1 {
       margin: 0 0 10px;
       font-size: clamp(2rem, 4vw, 3rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .subtitle {
       margin: 0 0 28px;
       max-width: 58ch;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-size: 0.95rem;
       font-weight: 600;
       color: #f8fafc;
     }

     .required {
       color: var(--accent-strong);
       margin-left: 4px;
     }

     input {
       width: 100%;
       border: 1px solid var(--field-border);
       border-radius: 14px;
       background: var(--field-bg);
       color: var(--text);
       padding: 14px 16px;
       font: inherit;
       outline: none;
       transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
     }

     input::placeholder { color: #64748b; }

     input:focus {
       border-color: color-mix(in srgb, var(--field-focus) 72%, white 0%);
       box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.18);
       transform: translateY(-1px);
     }

     .helper-text {
       color: var(--muted);
       font-size: 0.9rem;
       line-height: 1.5;
     }

     .validation-message {
       min-height: 1.25em;
       color: var(--error);
       font-size: 0.9rem;
       line-height: 1.4;
     }

     .form-field.has-error input {
       border-color: color-mix(in srgb, var(--error) 68%, white 0%);
       box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.14);
     }

     .actions {
       display: flex;
       justify-content: flex-end;
       padding-top: 6px;
     }

     button {
       border: 0;
       border-radius: 14px;
       padding: 14px 20px;
       background: linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%);
       color: white;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 16px 30px rgba(109, 40, 217, 0.28);
       transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
     }

     button:hover { transform: translateY(-1px); filter: brightness(1.05); }
     button:focus-visible { outline: 3px solid rgba(167, 139, 250, 0.55); outline-offset: 3px; }

     .success {
       display: none;
       margin-top: 18px;
       padding: 14px 16px;
       border-radius: 14px;
       background: rgba(52, 211, 153, 0.12);
       color: #bbf7d0;
       border: 1px solid rgba(52, 211, 153, 0.25);
     }

     .success.is-visible { display: block; }

     @media (max-width: 640px) {
       .card { padding: 24px 18px; border-radius: 20px; }
       .actions { justify-content: stretch; }
       button { width: 100%; }
     }
